public class MetadataSerializer {
    private static final Logger logger = Logger.getLogger(MetadataSerializer.class.getName());

    public static String serializeMetadataValue(Object value) {
        if (value == null) {
            return "null";
        }

        try {
            Method modelDumpMethod = value.getClass().getMethod("modelDump", boolean.class, boolean.class);
            if (modelDumpMethod != null) {
                try {
                    Object result = modelDumpMethod.invoke(value, true, true);
                    return result != null ? result.toString() : "null";
                } catch (Exception e) {
                    logger.warning("Failed to serialize metadata value: " + e.getMessage());
                    return value.toString();
                }
            }
        } catch (NoSuchMethodException e) {
        }

        return value.toString();
    }
}

