        if (a2aPart.getRoot() instanceof DataPart root
                && event.getLongRunningToolIds() != null
                && !event.getLongRunningToolIds().isEmpty()
                && root.getMetadata() != null
                && A2A_DATA_PART_METADATA_TYPE_FUNCTION_CALL.equals(
                        root.getMetadata().get(getAdkMetadataKey(A2A_DATA_PART_METADATA_TYPE_KEY)))
                && event.getLongRunningToolIds().contains(root.getData().get("id"))) {

            root.getMetadata().put(
                    getAdkMetadataKey(A2A_DATA_PART_METADATA_IS_LONG_RUNNING_KEY),
                    Boolean.TRUE
            );
        }
