public class ContextUtil {

    private static final String ADK_CONTEXT_ID_PREFIX = "adk";  
    private static final String ADK_CONTEXT_ID_SEPARATOR = "_";  

    public static String[] fromA2AContextId(String contextId) {
        if (contextId == null || contextId.isEmpty()) {
            return new String[]{null, null, null};
        }

        try {
            String[] parts = contextId.split(ADK_CONTEXT_ID_SEPARATOR);
            if (parts.length != 4) {
                return new String[]{null, null, null};
            }

            String prefix = parts[0];
            String appName = parts[1];
            String userId = parts[2];
            String sessionId = parts[3];

            if (ADK_CONTEXT_ID_PREFIX.equals(prefix)
                    && appName != null && !appName.isEmpty()
                    && userId != null && !userId.isEmpty()
                    && sessionId != null && !sessionId.isEmpty()) {
                return new String[]{appName, userId, sessionId};
            }
        } catch (Exception e) {

        }

        return new String[]{null, null, null};
    }
}

