public class AgentUtil {

    public static Class<? extends BaseAgent> resolveAgentClass(String agentClass) {
        String agentClassName = (agentClass != null && !agentClass.isEmpty()) ? agentClass : "LlmAgent";

        if (!agentClassName.contains(".")) {
            agentClassName = "google.adk.agents." + agentClassName;
        }

        try {
            Class<?> clazz = Class.forName(agentClassName);
            if (BaseAgent.class.isAssignableFrom(clazz)) {
                @SuppressWarnings("unchecked")
                Class<? extends BaseAgent> agentClazz = (Class<? extends BaseAgent>) clazz;
                return agentClazz;
            } else {
                throw new IllegalArgumentException(
                    "Invalid agent class `" + agentClassName + "`. It must be a subclass of BaseAgent."
                );
            }
        } catch (ClassNotFoundException e) {
            throw new IllegalArgumentException(
                "Invalid agent class `" + agentClassName + "`. Class not found.", e
            );
        }
    }
}

