}

public class ReflectionUtil {

    public static Object resolveFullyQualifiedName(String name) {
        try {
            int lastDotIndex = name.lastIndexOf('.');
            if (lastDotIndex == -1) {
                throw new IllegalArgumentException("Invalid fully qualified name: " + name);
            }

            String className = name.substring(0, lastDotIndex);
            String memberName = name.substring(lastDotIndex + 1);

            Class<?> clazz = Class.forName(className);
            try {
                return clazz.getField(memberName).get(null);
            } catch (NoSuchFieldException e) {
                return clazz.getMethod(memberName);
            }
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid fully qualified name: " + name, e);
        }
    }
}

public class AgentUtil {

    public static BaseAgent resolveAgentCodeReference(String code) {
        if (!code.contains(".")) {
            throw new IllegalArgumentException("Invalid code reference: " + code);
        }

        int lastDotIndex = code.lastIndexOf('.');
        String className = code.substring(0, lastDotIndex);
        String memberName = code.substring(lastDotIndex + 1);

        try {
            Class<?> clazz = Class.forName(className);
            Object obj;
            try {
                obj = clazz.getField(memberName).get(null);
            } catch (NoSuchFieldException e) {
                obj = clazz.getMethod(memberName);
            }

            if (obj instanceof java.lang.reflect.Method) {
                throw new IllegalArgumentException("Invalid agent reference to a callable: " + code);
            }

            if (!(obj instanceof BaseAgent)) {
                throw new IllegalArgumentException("Invalid agent reference to a non-agent instance: " + code);
            }

            return (BaseAgent) obj;
        } catch (ClassNotFoundException | IllegalAccessException | NoSuchMethodException e) {
            throw new IllegalArgumentException("Invalid agent reference: " + code, e);
        }
    }
}

public class CodeResolver {

    public static Object resolveCodeReference(CodeConfig codeConfig) {
        if (codeConfig == null || codeConfig.getName() == null || codeConfig.getName().isEmpty()) {
            throw new IllegalArgumentException("Invalid CodeConfig.");
        }

        String fullName = codeConfig.getName();
        int lastDotIndex = fullName.lastIndexOf('.');
        if (lastDotIndex == -1) {
            throw new IllegalArgumentException("Invalid CodeConfig name: " + fullName);
        }

        String className = fullName.substring(0, lastDotIndex);
        String memberName = fullName.substring(lastDotIndex + 1);

        try {
            Class<?> clazz = Class.forName(className);
            Object obj;
            try {
                obj = clazz.getField(memberName).get(null);
            } catch (NoSuchFieldException e) {
                obj = clazz.getMethod(memberName);
            }

            if (codeConfig.getArgs() != null && obj instanceof Method method) {
                List<Object> positionalArgs = new ArrayList<>();
                Map<String, Object> kwargs = new HashMap<>();

                for (CodeArg arg : codeConfig.getArgs()) {
                    if (arg.getName() != null) {
                        kwargs.put(arg.getName(), arg.getValue());
                    } else {
                        positionalArgs.add(arg.getValue());
                    }
                }


                return method.invoke(null, positionalArgs.toArray());
            } else {
                return obj;
            }
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to resolve code reference: " + fullName, e);
        }
    }
}

