public class Agent {

    private boolean isResumable;

    public boolean shouldPauseInvocation(Event event) {
        if (!isResumable) {
            return false;
        }

        if (event.getLongRunningToolIds() == null || event.getLongRunningToolIds().isEmpty()
                || event.getFunctionCalls() == null || event.getFunctionCalls().isEmpty()) {
            return false;
        }

        for (FunctionCall fc : event.getFunctionCalls()) {
            if (event.getLongRunningToolIds().contains(fc.getId())) {
                return true;
            }
        }

        return false;
    }

public class Agent {

    public Event findMatchingFunctionCall(Event functionResponseEvent) {
        List<FunctionResponse> functionResponses = functionResponseEvent.getFunctionResponses();
        if (functionResponses == null || functionResponses.isEmpty()) {
            return null;
        }
        String functionCallId = functionResponses.get(0).getId();

        List<Event> events = getEvents(true);
        for (int i = events.size() - 2; i >= 0; i--) { // 忽略最后一个事件
            Event event = events.get(i);
            for (FunctionCall fc : event.getFunctionCalls()) {
                if (fc.getId().equals(functionCallId)) {
                    return event;
                }
            }
        }
        return null;
    }

public class MessageUtils {

    public static List<HumanMessage> getLastHumanMessages(List<Event> events) {
        List<HumanMessage> messages = new ArrayList<>();

        for (int i = events.size() - 1; i >= 0; i--) {
            Event event = events.get(i);

            if (!messages.isEmpty() && !"user".equals(event.getAuthor())) {
                break;
            }

            if ("user".equals(event.getAuthor()) 
                    && event.getContent() != null 
                    && event.getContent().getParts() != null 
                    && !event.getContent().getParts().isEmpty()) {
                messages.add(new HumanMessage(event.getContent().getParts().get(0).getText()));
            }
        }

        Collections.reverse(messages);
        return messages;
    }

