public class Agent {

    private String name;

    public List<Message> getConversationWithAgent(List<Event> events) {
        List<Message> messages = new ArrayList<>();

        for (Event event : events) {
            if (event.getContent() == null || event.getContent().getParts() == null
                    || event.getContent().getParts().isEmpty()) {
                continue;
            }

            String text = event.getContent().getParts().get(0).getText();

            if ("user".equals(event.getAuthor())) {
                messages.add(new HumanMessage(text));
            } else if (name.equals(event.getAuthor())) {
                messages.add(new AIMessage(text));
            }
        }

        return messages;
    }
}

