public class Agent {

    private Object model;  
    private Agent parentAgent;
    private String name;

    public BaseLlm canonicalModel() {
        if (model instanceof BaseLlm) {
            return (BaseLlm) model;
        } else if (model instanceof String && !((String) model).isEmpty()) {
            return LLMRegistry.newLlm((String) model);
        } else {
            Agent ancestorAgent = parentAgent;
            while (ancestorAgent != null) {
                if (ancestorAgent instanceof LlmAgent) {
                    return ((LlmAgent) ancestorAgent).canonicalModel();
                }
                ancestorAgent = ancestorAgent.parentAgent;
            }
            throw new IllegalStateException("No model found for " + name + ".");
        }
    }
}

public class Agent {

    private List<ToolUnion> tools;
    private Object model;

    public CompletableFuture<List<BaseTool>> canonicalTools(ReadonlyContext ctx) {
        List<BaseTool> resolvedTools = new ArrayList<>();
        boolean multipleTools = tools.size() > 1;

        List<CompletableFuture<List<BaseTool>>> futures = new ArrayList<>();
        for (ToolUnion toolUnion : tools) {
            futures.add(_convertToolUnionToTools(toolUnion, ctx, model, multipleTools));
        }

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(v -> {
                    for (CompletableFuture<List<BaseTool>> f : futures) {
                        try {
                            resolvedTools.addAll(f.get());
                        } catch (Exception e) {
                            throw new RuntimeException(e);
                        }
                    }
                    return resolvedTools;
                });
    }

    private CompletableFuture<List<BaseTool>> _convertToolUnionToTools(
            ToolUnion toolUnion, ReadonlyContext ctx, Object model, boolean multipleTools) {
        return CompletableFuture.completedFuture(new ArrayList<>());
    }

    static class BaseTool {}
    static class ToolUnion {}
    static class ReadonlyContext {}
}

