public class AgentProcessor {

    private final BlockingQueue<Pair<Event, CompletableFuture<Void>>> queue = new LinkedBlockingQueue<>();
    private final Pair<Event, CompletableFuture<Void>> sentinel = new Pair<>(null, null);

    public void processAnAgent(AsyncIterable<Event> eventsForOneAgent) {
        CompletableFuture.runAsync(() -> {
            try {
                for (Event event : eventsForOneAgent) { // 假设 AsyncIterable 已被封装为可同步迭代
                    CompletableFuture<Void> resumeSignal = new CompletableFuture<>();
                    queue.put(new Pair<>(event, resumeSignal));
                    resumeSignal.get(); // 等待上游处理完成
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            } finally {
                try {
                    queue.put(sentinel);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public static class Pair<K, V> {
        public final K first;
        public final V second;
        public Pair(K first, V second) {
            this.first = first;
            this.second = second;
        }
    }

