public String formatEventsForPrompt(List<Event> events) {
    StringBuilder formattedHistory = new StringBuilder();
    for (Event event : events) {
        if (event.getContent() != null && event.getContent().getParts() != null) {
            for (ContentPart part : event.getContent().getParts()) {
                if (part.getText() != null) {
                    if (formattedHistory.length() > 0) {
                        formattedHistory.append("\n");
                    }
                    formattedHistory.append(event.getAuthor()).append(": ").append(part.getText());
                }
            }
        }
    }
    return formattedHistory.toString();
}

