public class ArtifactUtils {

    public static List<File> iterArtifactDirs(File root) {
        List<File> artifactDirs = new ArrayList<>();
        if (!root.exists() || !root.isDirectory()) {
            return artifactDirs;
        }

        File[] files = root.listFiles();
        if (files == null) {
            return artifactDirs;
        }

        for (File file : files) {
            if (file.isDirectory()) {
                File versionsDir = new File(file, "versions");
                if (versionsDir.exists() && versionsDir.isDirectory()) {
                    artifactDirs.add(file);
                } else {
                    artifactDirs.addAll(iterArtifactDirs(file)); // recursively check subdirectories
                }
            }
        }

        return artifactDirs;
    }
}

