private void deleteArtifactSync(String appName, String userId, String filename, @Nullable String sessionId) {
    Path artifactDir = artifactDir(appName, userId, sessionId, filename);
    if (Files.exists(artifactDir)) {
        try {

            Files.walk(artifactDir)
                .sorted(Comparator.reverseOrder())
                .forEach(path -> {
                    try {
                        Files.delete(path);
                    } catch (IOException e) {
                        throw new RuntimeException(e);
                    }
                });
            System.out.printf("Deleted artifact %s at %s%n", filename, artifactDir);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

public class ArtifactUtils {

    private static final Logger logger = Logger.getLogger(ArtifactUtils.class.getName());

    public static FileArtifactVersion readMetadata(Path path) {
        if (!Files.exists(path)) {
            return null;
        }
        try {
            String json = Files.readString(path);
            return FileArtifactVersion.modelValidateJson(json);
        } catch (ValidationException exc) {
            logger.warning(String.format("Failed to parse metadata at %s: %s", path, exc.getMessage()));
            return null;
        } catch (IllegalArgumentException exc) {
            logger.warning(String.format("Invalid metadata JSON at %s: %s", path, exc.getMessage()));
            return null;
        } catch (Exception exc) {
            logger.warning(String.format("Unexpected error reading metadata at %s: %s", path, exc.getMessage()));
            return null;
        }
    }
}

